#include <iostream>
#include <vector>

int main() {
    using namespace std;
    unsigned N;
    string S;
    cin >> N >> S;

    vector<unsigned> counter(2 * N + 1); // counter[d + N] = これまでの D_j のうち D_j = d を満たすものの個数（d は -N から N の範囲をとるので、N を足して 0 から 2N にしている）
    unsigned D{N};
    ++counter[D];
    unsigned long sum{}; // 現在の D 未満の d に対する counter[d] の総和
    unsigned long ans{};
    for (const auto c : S) {
        // sum と D を更新
        if (c == 'A')
            sum += counter[D++];
        if (c == 'B')
            sum -= counter[--D];

        // counter を更新
        ++counter[D];

        ans += sum;
    }

    cout << ans << endl;

    return 0;
}
